import sys, json, random, collections
sys.path.insert(0, "/app/tmp/t")
from run import run_json
import ref

MAXN = 4611686018427387903

def rhex(rng, n=None):
    if n is None: n = rng.randint(0, 6)
    return "".join(rng.choice("0123456789abcdef") for _ in range(2 * n))

def mkf(rng, level, cfg):
    """Generate frames that are mostly legal for the level."""
    r = rng.random()
    if r < 0.10: return {"type": "PADDING"}
    if r < 0.18: return {"type": "PING"}
    if r < 0.30:
        # ACK with ranges drawn from sent
        sent = cfg["sent"][level if level != "Z" else "A"]
        if sent and rng.random() < 0.7:
            x, y = rng.choice(sent)
            lo = rng.randint(x, y)
            hi = rng.randint(lo, y)
            return {"type": "ACK", "ranges": [[lo, hi]]}
        return {"type": "ACK", "ranges": [[0, rng.randint(0, 5)]]}
    if r < 0.55:
        return {"type": "CRYPTO", "offset": rng.randint(0, 14), "data_hex": rhex(rng)}
    if r < 0.85:
        sid = rng.choice([0, 0, 2, 2, 4, 6, 8, 10, 12])
        return {"type": "STREAM", "id": sid, "offset": rng.randint(0, 12),
                "data_hex": rhex(rng), "fin": rng.random() < 0.3}
    if r < 0.92:
        return {"type": "RESET_STREAM", "id": rng.choice([0, 2, 4, 6]),
                "final_size": rng.randint(0, 14)}
    if r < 0.97:
        return {"type": "STOP_SENDING", "id": rng.choice([0, 4, 8])}
    return {"type": "CLOSE", "app": rng.random() < 0.5, "code": rng.randint(0, 50)}

def mkranges(rng):
    out = []; cur = 0
    for _ in range(rng.randint(0, 3)):
        lo = cur + rng.randint(0, 4); hi = lo + rng.randint(0, 8)
        out.append([lo, hi]); cur = hi + 2
    return out

def mkcfg(rng):
    return {"early": rng.random() < 0.5,
            "overlap": rng.choice(["reject", "first", "first"]),
            "buffer_packets": rng.randint(1, 6),
            "idle_ms": rng.choice([0, 0, 0, 30]),
            "max_streams_bidi": rng.randint(1, 4),
            "max_streams_uni": rng.randint(1, 4),
            "max_stream_data": rng.randint(4, 20),
            "max_data": rng.randint(8, 60),
            "crypto_limit": rng.randint(4, 20),
            "sent": {"I": mkranges(rng), "H": mkranges(rng), "A": mkranges(rng)}}

def mkpkt(rng, level, cfg, pns):
    frames = []
    for _ in range(rng.randint(1, 5)):
        frames.append(mkf(rng, level, cfg))
    return {"level": level, "pn": rng.choice(pns), "auth": rng.random() < 0.95, "frames": frames}

def mktrace(rng, tid):
    cfg = mkcfg(rng)
    events = [{"t": 0, "op": "key", "level": "A", "action": "install"}]
    if rng.random() < 0.5:
        events.append({"t": 0, "op": "key", "level": "H", "action": "install"})
    t = 0
    pns = [0, 1, 2, 3]
    for _ in range(rng.randint(1, 14)):
        t += rng.choice([0, 1, 2, 3, 5])
        r = rng.random()
        if r < 0.12:
            events.append({"t": t, "op": "key", "level": rng.choice(["I", "H", "Z", "A"]),
                           "action": rng.choice(["install", "discard"])})
        elif r < 0.18:
            events.append({"t": t, "op": "tick"})
        else:
            k = rng.randint(1, 3)
            pkts = []
            for _ in range(k - 1):
                lv = rng.choice(["I", "H", "Z", "A"])
                pkts.append(mkpkt(rng, lv, cfg, pns))
            lv = rng.choice(["I", "H", "Z", "A"])
            pkts.append(mkpkt(rng, lv, cfg, pns))
            events.append({"t": t, "op": "datagram",
                           "bytes": rng.choice([1200, 1200, 1200, 1300]),
                           "packets": pkts})
    return {"id": tid, "config": cfg, "events": events}

stats = collections.Counter()
seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 5000
n = int(sys.argv[2]) if len(sys.argv) > 2 else 400
bad = 0
for i in range(n):
    rng = random.Random(seed0 + i)
    doc = {"version": 1, "traces": [mktrace(rng, "t%d" % k) for k in range(rng.randint(1, 3))]}
    rc, out, err = run_json(doc)
    if rc != 0:
        print("RC!=0", seed0 + i, err[:300]); bad += 1; continue
    got = json.loads(out); want = ref.run(doc)
    if got != want:
        bad += 1
        print("MISMATCH seed", seed0 + i)
        print("input:", json.dumps(doc))
        for g, w in zip(got["results"], want["results"]):
            if g != w:
                print(" got:", json.dumps(g)[:1200])
                print(" want:", json.dumps(w)[:1200])
        if bad >= 2: break
    for tr in got["results"]:
        stats["state:" + tr["connection"]["state"]] += 1
        stats["code:" + str(tr["connection"]["code"])] += 1
        for s in tr["streams"]:
            stats["stream"] += 1
            if s["reset"]: stats["stream:reset"] += 1
            if s["final_size"] is not None: stats["stream:fin"] += 1
            if s["delivered_hex"]: stats["stream:delivered"] += 1
        for c in tr["crypto"]:
            if c["highest"]: stats["crypto:" + c["level"]] += 1
            if c["contiguous_hex"]: stats["crypto:contig"] += 1
        for p in tr["packets"]:
            stats["p:" + p["status"] + "/" + p["reason"]] += 1
print("mismatches:", bad, "of", n)
for k, v in sorted(stats.items()): print("  %-40s %d" % (k, v))
PYEOF
